i2c_buses = {}
def i2c_bus(sda, scl, bloque):
    # Un bus por par de pines; los sensores que comparten SDA/SCL comparten el bus.
    clave = (sda, scl)
    if clave not in i2c_buses:
        try:
            if len(i2c_buses) < 2:
                i2c_buses[clave] = I2C(len(i2c_buses), scl=Pin(scl), sda=Pin(sda), freq=400000)
            else:
                i2c_buses[clave] = SoftI2C(scl=Pin(scl), sda=Pin(sda), freq=400000)
        except (ValueError, OSError) as error:
            rb_fail(bloque, "No se pudo iniciar I2C en SDA %s / SCL %s: %s" % (sda, scl, error))
    return i2c_buses[clave]
imu_bus = None
imu_direccion = 0x28
imu_cero = 0
imu_anterior = None
imu_acumulado = 0
def imu_acumular(heading):
    global imu_anterior, imu_acumulado
    if not math.isfinite(heading):
        return
    if imu_anterior is not None:
        delta = (heading - imu_anterior + 180) % 360 - 180
        if abs(delta) <= 90:
            imu_acumulado += delta
    imu_anterior = heading
def imu_configurar(sda, scl, bloque):
    global imu_bus, imu_direccion, imu_cero, imu_anterior, imu_acumulado
    bus = i2c_bus(sda, scl, bloque)
    # La BNO055 tarda unos 650 ms en responder después de encender.
    for _ in range(20):
        for direccion in (0x28, 0x29):
            try:
                if bus.readfrom_mem(direccion, 0x00, 1)[0] == 0xA0:
                    imu_direccion = direccion
                    break
            except OSError:
                pass
        else:
            time.sleep_ms(50)
            continue
        break
    else:
        rb_fail(bloque, "No se encontró la IMU BNO055 (0x28 o 0x29)")
    try:
        bus.writeto_mem(imu_direccion, 0x3D, bytes([0x00]))  # Modo configuración
        time.sleep_ms(25)
        bus.writeto_mem(imu_direccion, 0x3E, bytes([0x00]))  # Energía normal
        bus.writeto_mem(imu_direccion, 0x3B, bytes([0x00]))  # Ángulos en grados
        bus.writeto_mem(imu_direccion, 0x3D, bytes([0x08]))  # IMU: acelerómetro + giroscopio
        time.sleep_ms(25)
    except OSError:
        rb_fail(bloque, "No responde la IMU BNO055")
    imu_bus = bus
    imu_cero = 0
    imu_anterior = None
    imu_acumulado = 0
    imu_euler(bloque)
def imu_euler(bloque):
    if imu_bus is None:
        rb_fail(bloque, "Configura la IMU al iniciar")
    try:
        d = imu_bus.readfrom_mem(imu_direccion, 0x1A, 6)
    except OSError:
        rb_fail(bloque, "No responde la IMU BNO055")
    valores = []
    for i in (0, 2, 4):
        v = d[i] | d[i + 1] << 8
        valores.append((v - 65536 if v > 32767 else v) / 16)
    imu_acumular(valores[0])
    return valores  # Rumbo, alabeo y cabeceo en grados

