inline void imu_acumular(float heading) {
    if (!isfinite(heading)) return;
    if (imu_tiene_anterior) {
        float delta = heading - imu_anterior + 180;
        delta = delta - 360 * floorf(delta / 360) - 180;
        if (fabsf(delta) <= 90) imu_acumulado += delta;
    }
    imu_anterior = heading; imu_tiene_anterior = true;
}
