inline bool imu_iniciar(const char* bloque) {
    if (rb_failed) return true;
    if (!imu_bus) { rb_fail(bloque, "Configura la IMU al iniciar"); return true; }
    uint32_t elapsed = uint32_t(millis() - imu_started);
    if (imu_stage == 1) {
        if (elapsed < 50) return false;
        bool found = false;
        for (uint8_t address = 0x28; address <= 0x29; address++) { uint8_t id; if (rb_i2c_read(*imu_bus, address, 0x00, &id, 1) && id == 0xA0) { imu_direccion = address; found = true; break; } }
        imu_started = millis();
        if (!found) { if (++imu_intentos == 20) { rb_fail(bloque, "No se encontro BNO055 (0x28 o 0x29)"); return true; } return false; }
        if (!rb_i2c_write(*imu_bus, imu_direccion, 0x3D, 0)) { rb_fail(bloque, "No responde BNO055"); return true; } imu_stage = 2; return false;
    }
    if (imu_stage == 2) {
        if (elapsed < 25) return false;
        if (!rb_i2c_write(*imu_bus, imu_direccion, 0x3E, 0) || !rb_i2c_write(*imu_bus, imu_direccion, 0x3B, 0) || !rb_i2c_write(*imu_bus, imu_direccion, 0x3D, 8)) { rb_fail(bloque, "No responde BNO055"); return true; }
        imu_stage = 3; imu_started = millis(); return false;
    }
