def giro_diferencia(objetivo, angulo, bloque):
    objetivo = rb_finite(objetivo, bloque)
    angulo = rb_finite(angulo, bloque)
    return (objetivo - angulo + 180) % 360 - 180

def giro_ajustar(angulo, rango, bloque):
    angulo = rb_finite(angulo, bloque)
    if rango == "360":
