    return (angulo + 180) % 360 - 180

# Velocidad proporcional al error: máxima desde 45° de diferencia y nunca menos que la mínima
# (para vencer la fricción), salvo a menos de medio grado. Positiva = girar a la derecha.
def giro_velocidad(objetivo, angulo, maxima, minima, bloque):
    diferencia = giro_diferencia(objetivo, angulo, bloque)
    maxima = abs(rb_finite(maxima, bloque))
    minima = min(abs(rb_finite(minima, bloque)), maxima)
    if abs(diferencia) < 0.5:
        return 0
    velocidad = max(-maxima, min(maxima, diferencia * maxima / 45))
    if abs(velocidad) < minima:
        velocidad = minima if diferencia > 0 else -minima
    return velocidad

# Un reloj por bloque «llegó»: verdadero cuando el ángulo lleva «ms» dentro de la tolerancia.
giro_dentro = {}

