inline float giro_velocidad(float objetivo, float angulo, float maxima, float minima, const char* bloque) {
    float diferencia = giro_diferencia(objetivo, angulo, bloque);
    maxima = fabs(rb_finite(maxima, bloque));
    minima = fabs(rb_finite(minima, bloque));
    if (minima > maxima) minima = maxima;
    if (fabs(diferencia) < 0.5f) return 0;
    float velocidad = diferencia * maxima / 45.0f;
    if (velocidad > maxima) velocidad = maxima;
    if (velocidad < -maxima) velocidad = -maxima;
    if (fabs(velocidad) < minima) velocidad = diferencia > 0 ? minima : -minima;
    return velocidad;
}
// Un reloj por bloque «llegó» (hasta 8): verdadero cuando el ángulo lleva «ms» dentro de la tolerancia.
struct giro_reloj { const char* bloque; unsigned long desde; bool dentro; };
static giro_reloj giro_relojes[8];
inline giro_reloj& giro_buscar(const char* bloque) {
    for (uint8_t i = 0; i < 8; i++)
        if (giro_relojes[i].bloque && strcmp(giro_relojes[i].bloque, bloque) == 0) return giro_relojes[i];
    for (uint8_t i = 0; i < 8; i++)
        if (!giro_relojes[i].bloque) {
            giro_relojes[i].bloque = bloque;
            return giro_relojes[i];
        }
    return giro_relojes[7];
}
inline bool giro_llego(float objetivo, float angulo, float tolerancia, float ms, const char* bloque) {
    tolerancia = fabs(rb_finite(tolerancia, bloque));
    ms = rb_finite(ms, bloque);
    giro_reloj& reloj = giro_buscar(bloque);
    if (fabs(giro_diferencia(objetivo, angulo, bloque)) > tolerancia) {
        reloj.dentro = false;
        return false;
    }
    if (!reloj.dentro) {
        reloj.dentro = true;
        reloj.desde = millis();
    }
    return float(millis() - reloj.desde) >= ms;
}

# El reloj de Pybricks cuenta milisegundos desde que arranca el programa.
giro_reloj = StopWatch()

def giro_ms():
    return giro_reloj.time()

def giro_pasado(ahora, antes):
    return ahora - antes
def giro_diferencia(objetivo, angulo, bloque):
    objetivo = rb_finite(objetivo, bloque)
    angulo = rb_finite(angulo, bloque)
    return (objetivo - angulo + 180) % 360 - 180

def giro_ajustar(angulo, rango, bloque):
    angulo = rb_finite(angulo, bloque)
    if rango == "360":
        return angulo % 360
    return (angulo + 180) % 360 - 180

# Velocidad proporcional al error: máxima desde 45° de diferencia y nunca menos que la mínima
# (para vencer la fricción), salvo a menos de medio grado. Positiva = girar a la derecha.
def giro_velocidad(objetivo, angulo, maxima, minima, bloque):
    diferencia = giro_diferencia(objetivo, angulo, bloque)
    maxima = abs(rb_finite(maxima, bloque))
    minima = min(abs(rb_finite(minima, bloque)), maxima)
    if abs(diferencia) < 0.5:
        return 0
    velocidad = max(-maxima, min(maxima, diferencia * maxima / 45))
    if abs(velocidad) < minima:
        velocidad = minima if diferencia > 0 else -minima
    return velocidad

# Un reloj por bloque «llegó»: verdadero cuando el ángulo lleva «ms» dentro de la tolerancia.
giro_dentro = {}

def giro_llego(objetivo, angulo, tolerancia, ms, bloque):
    tolerancia = abs(rb_finite(tolerancia, bloque))
    ms = rb_finite(ms, bloque)
    if abs(giro_diferencia(objetivo, angulo, bloque)) > tolerancia:
        giro_dentro.pop(bloque, None)
        return False
    ahora = giro_ms()
    if bloque not in giro_dentro:
        giro_dentro[bloque] = ahora
    return giro_pasado(ahora, giro_dentro[bloque]) >= ms
